// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.eclipse.rdf4j.sail.lmdb.LmdbPackedRuleDifferentialSupport.check;

import java.io.File;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * End-to-end guards for the packed planner's EXISTS dependency analysis on LMDB: an OPTIONAL binding that only an
 * EXISTS / NOT EXISTS inner FILTER reads is observed and must survive unused-OPTIONAL pruning (DISTINCT, REDUCED, COUNT
 * DISTINCT observers) and projection-below-ORDER.
 */
class LmdbExistsReferencedBindingsTest {

	private static final String DATA = """
			@prefix : <urn:t:> .
			:a :p 1 ; :q :k ; :r :k .
			:b :p 2 ; :q :k2 ; :r :k3 .
			:c :p 3 .
			""";

	@Test
	void distinctExistsInnerFilterObservesOptionalBinding(@TempDir File dir) throws Exception {
		String query = "SELECT DISTINCT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } "
				+ "FILTER EXISTS { ?s :r ?c FILTER(?c = ?b) } }";
		check(dir, DATA, query, List.of("s=urn:t:a"));
	}

	@Test
	void reducedExistsInnerFilterObservesOptionalBinding(@TempDir File dir) throws Exception {
		String query = "SELECT REDUCED ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } "
				+ "FILTER EXISTS { ?s :r ?c FILTER(?c = ?b) } }";
		check(dir, DATA, query, List.of("s=urn:t:a"));
	}

	@Test
	void distinctNotExistsInnerFilterObservesOptionalBinding(@TempDir File dir) throws Exception {
		String query = "SELECT DISTINCT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } "
				+ "FILTER NOT EXISTS { ?s :r ?c FILTER(?c = ?b) } }";
		check(dir, DATA, query, List.of("s=urn:t:b", "s=urn:t:c"));
	}

	@Test
	void countDistinctExistsInnerFilterObservesOptionalBinding(@TempDir File dir) throws Exception {
		String query = "SELECT (COUNT(DISTINCT ?s) AS ?n) WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } "
				+ "FILTER EXISTS { ?s :r ?c FILTER(?c = ?b) } }";
		check(dir, DATA, query, List.of("n=1"));
	}

	@Test
	void plainSelectExistsInnerFilterBaseline(@TempDir File dir) throws Exception {
		String query = "SELECT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } "
				+ "FILTER EXISTS { ?s :r ?c FILTER(?c = ?b) } }";
		check(dir, DATA, query, List.of("s=urn:t:a"));
	}

	/**
	 * The ORDER key EXISTS reads the optional ?b through its inner FILTER; pushing the projection below the ORDER would
	 * drop ?b before the sort evaluates it. The body compares two variables so that no LMDB pre-pass can fold the
	 * correlated FILTER (the {@code FILTER(?b = :k)} spelling is folded to EmptySet before the packed planner runs,
	 * which is a separate LMDB-rewrite defect).
	 */
	@Test
	void projectionBelowOrderExistsOrderKey(@TempDir File dir) throws Exception {
		String data = """
				@prefix : <urn:t:> .
				:a :p 1 ; :q :z ; :r :k .
				:b :p 2 ; :q :k ; :r :k .
				""";
		check(dir, data,
				"SELECT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } } ORDER BY DESC(EXISTS { ?s :r ?c FILTER(?c = ?b) }) ?s LIMIT 1",
				List.of("s=urn:t:b"));
	}
}
